package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicLong;import java.util.function.*;
/** One coalesced off-main reader and an owned, nonce-fenced notification receipt. */
final class SmartBedtimeRuntime {
 interface Journal{SharedPreferences open(Context c);}interface Projection{long next(Context c,Alarm a,long now,ZoneId zone);}
 interface Output{String access(Context c);void schedule(Context c,String nonce,long at);void cancel(Context c);void show(Context c);default void show(Context c,String series,int step){show(c);}default void dismissShown(Context c){}}
 static final String ACTION="org.sleepwell.SMART_BEDTIME",DISMISS="org.sleepwell.DISMISS_SMART_BEDTIME";static final long LATE=15*60000L,REPEAT_WINDOW=2*3600000L;
 static final Output PLATFORM=new Output(){public String access(Context c){if(!Scheduler.allowed(c))return "Allow Alarms & reminders to schedule this reminder.";NotificationManager nm=c.getSystemService(NotificationManager.class);if(!nm.areNotificationsEnabled())return "Allow notifications to see bedtime reminders.";NotificationChannel channel=nm.getNotificationChannel(Notifications.BED);return channel!=null&&channel.getImportance()==NotificationManager.IMPORTANCE_NONE?"The Bedtime reminders notification channel is blocked.":"";}public void schedule(Context c,String nonce,long at){c.getSystemService(AlarmManager.class).setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c,nonce,at));}public void cancel(Context c){c.getSystemService(AlarmManager.class).cancel(pending(c,"",0));}public void show(Context c){show(c,"",0);}public void show(Context c,String series,int step){Notifications.channels(c);Notification.Builder notification=new Notification.Builder(c,Notifications.BED).setSmallIcon(R.drawable.ic_moon).setContentTitle(step==0?"Time to wind down":"Bedtime reminder").setContentText("Your saved goal and next alarm set this reminder. Start tracking or dismiss tonight's reminders.").setContentIntent(Notifications.home(c)).setAutoCancel(true).setSilent(true).setOnlyAlertOnce(true);if(!series.isEmpty()){PendingIntent dismiss=PendingIntent.getBroadcast(c,7464,new Intent(c,SmartBedtimeReceiver.class).setAction(DISMISS).setData(android.net.Uri.parse("sleepwell://dismiss-smart-bedtime/"+series)).putExtra("series",series),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);notification.setDeleteIntent(dismiss).addAction(new Notification.Action.Builder(null,"Dismiss tonight",dismiss).build());}c.getSystemService(NotificationManager.class).notify("smart-bedtime",300,notification.build());}public void dismissShown(Context c){c.getSystemService(NotificationManager.class).cancel("smart-bedtime",300);}};
 static Output output=PLATFORM;static Journal journal=c->c.getSharedPreferences("sleepwell-smart-bedtime",0);static Projection projection=AlarmSkips::next;static LongSupplier clock=System::currentTimeMillis;static Supplier<ZoneId> zone=ZoneId::systemDefault;
 static final class Snapshot{final SleepPlan plan;final SmartBedtime.Result result;final boolean tracking;final String access;Snapshot(SleepPlan p,SmartBedtime.Result r,boolean tracking,String access){plan=p;result=r;this.tracking=tracking;this.access=access;}}
 private static final ExecutorService worker=Executors.newSingleThreadExecutor(r->new Thread(r,"SleepWell smart bedtime"));private static final AtomicLong generation=new AtomicLong();private static boolean queued,dirty;private static Request latest;private static SharedPreferences.OnSharedPreferenceChangeListener listener;private static SharedPreferences observed,delays;
 private static final class Request{final Context c;final Records.Factory records;final SleepPlans.Factory plans;final TrackingDelaySettings.Factory delay;final Journal journal;final Output output;final Projection projection;final LongSupplier clock;final Supplier<ZoneId> zone;Request(Context context){c=context.getApplicationContext();records=Records.factory;plans=SleepPlans.factory;delay=TrackingDelaySettings.factory;journal=SmartBedtimeRuntime.journal;output=SmartBedtimeRuntime.output;projection=SmartBedtimeRuntime.projection;clock=SmartBedtimeRuntime.clock;zone=SmartBedtimeRuntime.zone;}}
 static Snapshot preview(Context c,SleepPlan draft){return read(new Request(c),draft);}
 private static Snapshot read(Request q,SleepPlan draft){SleepPlan p=draft==null?new SleepPlans.Repository(q.plans.open(q.c)).load():draft.copy();long now=q.clock.getAsLong();ZoneId z=q.zone.get();int delay=new TrackingDelaySettings(q.delay.open(q.c)).minutes();List<Alarm> alarms;List<RecordEntry> records;try(Store store=q.records.open(q.c)){android.database.sqlite.SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{alarms=store.alarms();records=new ArrayList<>(Records.all(store));records.removeIf(r->{try{SensorProvenance.validate(r.sensor,r.sensorConfig);return false;}catch(IllegalArgumentException invalid){return true;}});db.setTransactionSuccessful();}finally{db.endTransaction();}}SmartBedtime.Result result=SmartBedtime.calculate(p,alarms,records,now,z,delay,(a,n,t)->q.projection.next(q.c,a,n,t));return new Snapshot(p,result,TrackingService.running||Prefs.flag(q.c,"tracking"),q.output.access(q.c));}
 static void changed(Context c){try{if(SleepPlans.load(c).smartBedtime)reconcile(c);}catch(RuntimeException ignored){}}
 static void reconcile(Context c){if(output==PLATFORM&&(Records.factory!=Records.PRODUCTION||SleepPlans.factory!=SleepPlans.PRODUCTION))return;long next=generation.incrementAndGet();if(next<=0)return;synchronized(SmartBedtimeRuntime.class){latest=new Request(c);dirty=true;if(queued)return;queued=true;}worker.execute(SmartBedtimeRuntime::refreshLoop);}
 private static void refreshLoop(){for(;;){Request q;long version;synchronized(SmartBedtimeRuntime.class){q=latest;dirty=false;version=generation.get();}refresh(q,version);synchronized(SmartBedtimeRuntime.class){if(dirty)continue;queued=false;return;}}}
 private static void status(SharedPreferences p,String value){if(!p.edit().putString("status",value).commit())throw new IllegalStateException("Reminder status could not be stored.");}
 private static SharedPreferences.Editor receiptOff(SharedPreferences.Editor edit){return edit.remove("nonce").remove("at").remove("proof").remove("identity").remove("repeatStep");}
 private static SharedPreferences.Editor seriesOff(SharedPreferences.Editor edit){for(String key:List.of("series","seriesProof","seriesIdentity","seriesAt","seriesAlarmAt","seriesUntil","seriesRepeats","seriesLast","seriesEnded","seriesElapsed","seriesWall","seriesBoot"))edit.remove(key);return edit;}
 private static void clear(SharedPreferences p,String value){if(!seriesOff(receiptOff(p.edit())).putString("status",value).commit())throw new IllegalStateException("Reminder ownership could not be stored.");}
 private static void stop(Request q,SharedPreferences saved,String value,boolean hide){clear(saved,value);q.output.cancel(q.c);if(hide)q.output.dismissShown(q.c);}
 private static SmartBedtime.Result seriesResult(Request q,Snapshot s,SharedPreferences saved){SmartBedtime.Result r=s.result;long base=saved.getLong("seriesAt",0);if(r.fallback&&base>0&&s.plan.nextReminder(base-1,q.zone.get())==base)return new SmartBedtime.Result(base,0,0,0,0,0,r.observed,r.shortfall,true,"",s.plan,q.zone.get());return r;}
 private static void install(Request q,SharedPreferences saved,SmartBedtime.Result r,long due,boolean repeat,long version){String nonce=UUID.randomUUID().toString();if(!saved.edit().putString("nonce",nonce).putLong("at",due).putString("proof",r.proof).putString("identity",r.identity).putBoolean("repeatStep",repeat).putString("status",repeat?"Scheduling silent repeat…":"Scheduling reminder…").commit())throw new IllegalStateException("Reminder ownership could not be saved.");if(version!=generation.get()){receiptOff(saved.edit()).putString("status","Recalculating reminder…").commit();return;}q.output.schedule(q.c,nonce,due);status(saved,repeat?"Silent repeat scheduled.":"Reminder scheduled.");}
 private static void finishSeries(Request q,SharedPreferences saved,String message){if(!receiptOff(saved.edit()).putBoolean("seriesEnded",true).putString("status",message).commit())throw new IllegalStateException("Reminder result could not be stored.");q.output.cancel(q.c);}
 private static boolean seriesClock(Request q,SharedPreferences saved){long anchor=saved.getLong("seriesElapsed",-1),wall=saved.getLong("seriesWall",-1),elapsed=SystemClock.elapsedRealtime();int boot=android.provider.Settings.Global.getInt(q.c.getContentResolver(),android.provider.Settings.Global.BOOT_COUNT,0);return anchor>=0&&wall>0&&elapsed>=anchor&&elapsed-anchor<REPEAT_WINDOW&&saved.getInt("seriesBoot",-1)==boot&&Math.abs((q.clock.getAsLong()-wall)-(elapsed-anchor))<=60000;}
 private static void nextRepeat(Request q,SharedPreferences saved,Snapshot s,SmartBedtime.Result r,long version){if(saved.getBoolean("seriesEnded",false))return;if(!seriesClock(q,saved)){finishSeries(q,saved,"Previous repeat window ended after restart or clock change.");return;}int used=saved.getInt("seriesRepeats",0);long last=saved.getLong("seriesLast",0),until=saved.getLong("seriesUntil",0),now=q.clock.getAsLong();if(s.plan.smartRepeatMinutes<=0||used>=s.plan.smartRepeatLimit){finishSeries(q,saved,"Bedtime reminder complete. No further repeats.");return;}long due=last+s.plan.smartRepeatMinutes*60000L;if(last<=0||until<=now||due>=until){finishSeries(q,saved,"Bedtime repeat window ended. Wake-up alarm unchanged.");return;}if(now-due>LATE){finishSeries(q,saved,"A repeat was missed. No catch-up reminders will be sent.");return;}install(q,saved,r,Math.max(due,now+1000),true,version);}
 private static void refresh(Request q,long version){SharedPreferences saved=q.journal.open(q.c);try{SleepPlan plan=new SleepPlans.Repository(q.plans.open(q.c)).load();if(!plan.smartBedtime||!plan.reminder){stop(q,saved,"Smart Bedtime is off.",true);return;}Snapshot s=read(q,plan);if(version!=generation.get())return;SmartBedtime.Result r=s.result;if(s.tracking){saved.edit().putString("consumed",r.identity).commit();stop(q,saved,"Tonight's reminder ended because tracking started.",true);return;}if(!s.access.isEmpty()){stop(q,saved,s.access,false);return;}
  String series=saved.getString("series","");if(!series.isEmpty()){r=seriesResult(q,s,saved);if(r.identity.equals(saved.getString("seriesIdentity",""))){if(!r.proof.equals(saved.getString("seriesProof",""))||!r.issue.isEmpty()){stop(q,saved,"Repeat series ended after the plan or recording history changed.",true);return;}nextRepeat(q,saved,s,r,version);return;}stop(q,saved,"Previous reminder occurrence ended.",true);r=s.result;}
  String problem=!r.issue.isEmpty()?r.issue:r.identity.equals(saved.getString("consumed",""))?"Already handled this alarm's bedtime reminder.":r.at<=q.clock.getAsLong()?"The calculated reminder time has passed. The wake-up alarm is unchanged.":"";if(!problem.isEmpty()){stop(q,saved,problem,false);return;}install(q,saved,r,r.at,false,version);
 }catch(RuntimeException failure){try{stop(q,saved,"Reminder needs attention: "+message(failure),false);}catch(RuntimeException ignored){}}}
 static void deliver(Context c,String nonce,long at,Runnable completed){Request q=new Request(c);if(q.output==PLATFORM&&(q.records!=Records.PRODUCTION||q.plans!=SleepPlans.PRODUCTION)){completed.run();return;}worker.execute(()->{try{deliver(q,nonce,at);}finally{completed.run();}});}
 private static void deliver(Request q,String nonce,long at){SharedPreferences saved=q.journal.open(q.c);try{if(nonce==null||nonce.isEmpty()||!nonce.equals(saved.getString("nonce",""))||at!=saved.getLong("at",0))return;long version=generation.get(),now=q.clock.getAsLong();if(now<at-1000)return;if(now-at>LATE){stop(q,saved,"Reminder missed its delivery window. Wake-up alarm unchanged.",false);return;}Snapshot s=read(q,null);boolean repeat=saved.getBoolean("repeatStep",false);SmartBedtime.Result r=repeat?seriesResult(q,s,saved):s.result;if(!repeat&&r.fallback&&s.plan.nextReminder(at-1,q.zone.get())==at)r=new SmartBedtime.Result(at,0,0,0,0,0,r.observed,r.shortfall,true,"",s.plan,q.zone.get());if(version!=generation.get()||!s.plan.reminder||!s.plan.smartBedtime||!s.access.isEmpty()||!r.proof.equals(saved.getString("proof",""))){reconcile(q.c);return;}if(s.tracking){saved.edit().putString("consumed",r.identity).commit();stop(q,saved,"Tonight's reminders ended because tracking started.",true);return;}
  String series;int used;if(repeat){series=saved.getString("series","");used=saved.getInt("seriesRepeats",0)+1;if(series.isEmpty()||!seriesClock(q,saved)||saved.getBoolean("seriesEnded",false)||!r.identity.equals(saved.getString("seriesIdentity",""))||!r.proof.equals(saved.getString("seriesProof",""))||s.plan.smartRepeatMinutes<=0||used>s.plan.smartRepeatLimit||now>=saved.getLong("seriesUntil",0)){finishSeries(q,saved,"Bedtime repeat window ended.");return;}}else{if(r.identity.equals(saved.getString("consumed","")))return;series=UUID.randomUUID().toString();used=0;}
  SharedPreferences.Editor claim=receiptOff(saved.edit()).putString("consumed",r.identity).putString("series",series).putString("seriesProof",r.proof).putString("seriesIdentity",r.identity).putLong("seriesAt",r.at).putLong("seriesAlarmAt",r.alarmAt).putInt("seriesRepeats",used).putLong("seriesLast",now).putBoolean("seriesEnded",false).putString("status",repeat?"Silent repeat claimed for delivery.":"Reminder claimed for delivery.");if(!repeat)claim.putLong("seriesUntil",Math.min(now+REPEAT_WINDOW,r.alarmAt>0?r.alarmAt:Long.MAX_VALUE)).putLong("seriesElapsed",SystemClock.elapsedRealtime()).putLong("seriesWall",now).putInt("seriesBoot",android.provider.Settings.Global.getInt(q.c.getContentResolver(),android.provider.Settings.Global.BOOT_COUNT,0));if(!claim.commit())throw new IllegalStateException("Reminder receipt could not be saved.");if(version!=generation.get())return;q.output.show(q.c,series,used);status(saved,repeat?"Silent bedtime repeat shown.":"Bedtime reminder shown.");nextRepeat(q,saved,s,r,version);
 }catch(RuntimeException failure){try{stop(q,saved,"Reminder needs attention: "+message(failure),false);}catch(RuntimeException ignored){}}}
 static void dismiss(Context c,String series,Runnable completed){Request q=new Request(c);if(q.output==PLATFORM&&(q.records!=Records.PRODUCTION||q.plans!=SleepPlans.PRODUCTION)){completed.run();return;}worker.execute(()->{try{SharedPreferences saved=q.journal.open(q.c);if(series!=null&&!series.isEmpty()&&series.equals(saved.getString("series",""))){stop(q,saved,"Tonight's reminders dismissed.",true);}}finally{completed.run();}});}
 static void observe(Context c){if(listener!=null)return;Context app=c.getApplicationContext();observed=Prefs.of(app);delays=app.getSharedPreferences("sleepwell-tracking-delay",0);listener=(p,key)->{if(p==delays&&"minutes".equals(key)||p==observed&&(key==null||Set.of("goal","bedtime","bedReminder","bedReminderAdvance","smartBedtime","noAlarmBedtime","smartBedtimeRepeatMinutes","smartBedtimeRepeatLimit","planRevision","tracking").contains(key)))reconcile(app);};observed.registerOnSharedPreferenceChangeListener(listener);delays.registerOnSharedPreferenceChangeListener(listener);if(observed.getBoolean("smartBedtime",false))reconcile(app);}
 static void drain(long timeout)throws Exception{long end=System.nanoTime()+TimeUnit.MILLISECONDS.toNanos(timeout);for(;;){worker.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);synchronized(SmartBedtimeRuntime.class){if(!queued)return;}if(System.nanoTime()>end)throw new TimeoutException("Smart Bedtime worker busy");}}
 private static PendingIntent pending(Context c,String nonce,long at){return PendingIntent.getBroadcast(c,7463,new Intent(c,SmartBedtimeReceiver.class).setAction(ACTION).putExtra("nonce",nonce).putExtra("at",at),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static String message(RuntimeException e){return e.getMessage()==null?"Scheduling unavailable.":e.getMessage();}
 private SmartBedtimeRuntime(){}
}
